{[Fact] public void PaperKeepsInvalidAttemptFailClosed(){string p=File.ReadAllText(Path.Combine(Root(),"ResearchPaper","section","md base","3_Architectural_Overview_and_Frontend_Contract.md"));Assert.Contains("Default, cross-attempt or reconstructed `VliwOperationId`",p,StringComparison.Ordinal);Assert.Contains("fail-closed execution or bounded-retirement contract violation",p,StringComparison.Ordinal);Assert.Contains("does not create a replay token",p,StringComparison.Ordinal);Assert.Contains("no shared invalid result",p,StringComparison.Ordinal);}private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"ResearchPaper")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
